const crypto = require("crypto");
const bunGateway = require("../../../../node-red/lib/bun-gateway");

var log = require("@node-red/util").log; // TODO: separate module
var Tokens;
var Users;
var Permissions;
var Strategies;

var server;
var settings;
var runtimeAPI;

var bunSocketMap;
var commsPath;
var activeConnections = [];

var anonymousUser;

var heartbeatTimer;
var lastSentTime;

var hasBunWebSocket = typeof Bun !== "undefined" && typeof Bun.serve === "function";

function getCommsPath() {
    var path = settings.httpAdminRoot || "/";
    return (path.slice(0,1) != "/" ? "/":"") + path + (path.slice(-1) == "/" ? "":"/") + "comms";
}

function createNodeLikeRequest(request) {
    var headers = {};
    request.headers.forEach(function(value,key) {
        headers[key.toLowerCase()] = value;
    });
    var parsed = new URL(request.url);
    return {
        headers: headers,
        method: request.method,
        url: parsed.pathname + parsed.search
    };
}

function toMessageString(message) {
    if (typeof message === "string") {
        return message;
    }
    if (typeof Buffer !== "undefined" && Buffer.isBuffer(message)) {
        return message.toString();
    }
    if (message instanceof Uint8Array || message instanceof ArrayBuffer) {
        return Buffer.from(message).toString();
    }
    return String(message);
}

function createBunSocketAdapter(bunSocket) {
    var handlers = {};
    return {
        send: function(payload) {
            bunSocket.send(payload);
        },
        close: function() {
            bunSocket.close();
        },
        on: function(event, handler) {
            handlers[event] = handler;
        },
        emit: function(event, a, b) {
            if (handlers[event]) {
                handlers[event](a,b);
            }
        }
    };
}

function startBunCommsServer() {
    bunSocketMap = new WeakMap();
    var tokenHeader = Users.tokenHeader();

    bunGateway.registerWebSocket(commsPath, {
        authorize: function(request) {
            if (tokenHeader !== null && request.headers.get(tokenHeader)) {
                return Strategies.authenticateUserToken(createNodeLikeRequest(request)).then(function(user) {
                    return { user: user || null };
                }).catch(function() {
                    log.audit({event: "comms.auth.fail"});
                    return { deny: true, status: 401, body: "Unauthorized" };
                });
            }
            return { user: null };
        },
        open: function(socket, context) {
            var adapter = createBunSocketAdapter(socket);
            bunSocketMap.set(socket, adapter);
            var user = context && context.user ? context.user : null;
            var connection = new CommsConnection(adapter, user);
            socket.data.connection = connection;
        },
        message: function(socket, message) {
            var adapter = bunSocketMap.get(socket);
            if (adapter) {
                adapter.emit('message', toMessageString(message), false);
            }
        },
        close: function(socket) {
            var adapter = bunSocketMap.get(socket);
            if (adapter) {
                adapter.emit('close');
            }
            bunSocketMap.delete(socket);
        },
        error: function(socket, error) {
            var adapter = bunSocketMap.get(socket);
            if (adapter) {
                adapter.emit('error', error);
            }
        }
    });
}

function init(_server,_settings,_runtimeAPI) {
    server = _server;
    settings = _settings;
    runtimeAPI = _runtimeAPI;
    Tokens = require("../auth/tokens");
    Tokens.onSessionExpiry(handleSessionExpiry);
    Users = require("../auth/users");
    Permissions = require("../auth/permissions");
    Strategies = require("../auth/strategies");

}
function handleSessionExpiry(session) {
    activeConnections.forEach(connection => {
        if (connection.token === session.accessToken) {
            connection.ws.send(JSON.stringify({auth:"fail"}));
            connection.ws.close();
        }
    })
}

function CommsConnection(ws, user) {
    this.session = crypto.randomBytes(32).toString('base64');
    this.ws = ws;
    this.stack = [];
    this.user = user;
    this.lastSentTime = 0;
    var self = this;

    log.audit({event: "comms.open"});
    log.trace("comms.open "+self.session);
    var preAuthed = !!user;
    var pendingAuth = !this.user && (settings.adminAuth != null);

    if (!pendingAuth) {
        addActiveConnection(self);
    }
    ws.on('close',function() {
        log.audit({event: "comms.close",user:self.user, session: self.session});
        log.trace("comms.close "+self.session);
        removeActiveConnection(self);
    });

    const handleAuthPacket = function(msg) {
        Tokens.get(msg.auth).then(function(client) {
            if (client) {
                Users.get(client.user).then(function(user) {
                    if (user) {
                        self.user = user;
                        log.audit({event: "comms.auth",user:self.user});
                        completeConnection(msg, client.scope,msg.auth,true);
                    } else {
                        log.audit({event: "comms.auth.fail"});
                        completeConnection(msg, null,null,false);
                    }
                });
            } else {
                Users.tokens(msg.auth).then(function(user) {
                    if (user) {
                        self.user = user;
                        log.audit({event: "comms.auth",user:self.user});
                        completeConnection(msg, user.permissions,msg.auth,true);
                    } else {
                        log.audit({event: "comms.auth.fail"});
                        completeConnection(msg, null,null,false);
                    }
                });
            }
        });
    }
    const completeConnection = function(msg, userScope, session, sendAck) {
        try {
            if (!userScope || !Permissions.hasPermission(userScope,"status.read")) {
                ws.send(JSON.stringify({auth:"fail"}));
                ws.close();
            } else {
                pendingAuth = false;
                addActiveConnection(self);
                self.token = msg.auth;
                if (sendAck) {
                    ws.send(JSON.stringify({auth:"ok"}));
                }
            }
        } catch(err) {
            console.log(err.stack);
            // Just in case the socket closes before we attempt
            // to send anything.
        }
    }
    ws.on('message', function(data,flags) {
        var msg = null;
        try {
            msg = JSON.parse(data);
        } catch(err) {
            log.trace("comms received malformed message : "+err.toString());
            return;
        }
        if (!pendingAuth) {
            if (msg.auth) {
                handleAuthPacket(msg)
            } else if (msg.subscribe) {
                self.subscribe(msg.subscribe);
                // handleRemoteSubscription(ws,msg.subscribe);
            } else if (msg.topic) {
                runtimeAPI.comms.receive({
                    user: self.user,
                    client: self,
                    topic: msg.topic,
                    data: msg.data
                })
            }
        } else {
            if (msg.auth) {
                handleAuthPacket(msg)
            } else {
                if (anonymousUser) {
                    log.audit({event: "comms.auth",user:anonymousUser});
                    self.user = anonymousUser;
                    completeConnection(msg, anonymousUser.permissions, null, false);
                    //TODO: duplicated code - pull non-auth message handling out
                    if (msg.subscribe) {
                        self.subscribe(msg.subscribe);
                    }
                } else {
                    log.audit({event: "comms.auth.fail"});
                    completeConnection(msg, null,null,false);
                }
            }
        }
    });
    ws.on('error', function(err) {
        log.warn(log._("comms.error",{message:err.toString()}));
    });
}

CommsConnection.prototype.send = function(topic,data) {
    if (topic && data) {
        this.stack.push({topic:topic,data:data});
    }
    this._queueSend();
}
CommsConnection.prototype._queueSend = function() {
    var self = this;
    if (!this._xmitTimer) {
        this._xmitTimer = setTimeout(function() {
            try {
                self.ws.send(JSON.stringify(self.stack.splice(0,50)));
                self.lastSentTime = Date.now();
            } catch(err) {
                removeActiveConnection(self);
                log.warn(log._("comms.error-send",{message:err.toString()}));
            }
            delete self._xmitTimer;
            if (self.stack.length > 0) {
                self._queueSend();
            }
        },50);
    }
}


CommsConnection.prototype.subscribe = function(topic) {
    runtimeAPI.comms.subscribe({
        user: this.user,
        client: this,
        topic: topic
    })
}

function start() {
    if (!settings.disableEditor) {
        Users.default().then(function(_anonymousUser) {
            anonymousUser = _anonymousUser;
            var webSocketKeepAliveTime = settings.webSocketKeepAliveTime || 15000;
            commsPath = getCommsPath();

            if (!hasBunWebSocket) {
                throw new Error("Bun.serve is required for editor comms websocket support");
            }

            try {
                startBunCommsServer();
            } catch(err) {
                log.warn(log._("comms.error-server",{message:err.toString()}));
                throw err;
            }

            lastSentTime = Date.now();

            heartbeatTimer = setInterval(function() {
                var now = Date.now();
                if (now-lastSentTime > webSocketKeepAliveTime) {
                    activeConnections.forEach(connection => connection.send("hb",lastSentTime));
                }
            }, webSocketKeepAliveTime);
        });
    }
}

function stop() {
    if (heartbeatTimer) {
        clearInterval(heartbeatTimer);
        heartbeatTimer = null;
    }
    if (commsPath) {
        bunGateway.unregisterWebSocket(commsPath);
    }
    bunSocketMap = null;
}

function addActiveConnection(connection) {
    activeConnections.push(connection);
    runtimeAPI.comms.addConnection({client: connection});
}
function removeActiveConnection(connection) {
    for (var i=0;i<activeConnections.length;i++) {
        if (activeConnections[i] === connection) {
            activeConnections.splice(i,1);
            runtimeAPI.comms.removeConnection({client:connection})
            break;
        }
    }
}

module.exports = {
    init:init,
    start:start,
    stop:stop
}
